def FRONTIER(s, e):
    """ Full subtrees covering [s, e), ascending by start. """
    nodes = []
    while s < e:
        size = 1
        while s % (size * 2) == 0 and s + size * 2 <= e:
            size *= 2
        nodes.append((s, s + size))
        s += size
    return nodes

def TILING(L, n):
    """ Full subtrees partitioning [0, n), refined at every
        endpoint appearing in L. """
    points = {0, n}
    for (start, end) in L:
        points.add(start)
        points.add(end)
    breakpoints = sorted(points)
    tiles = []
    for p, q in zip(breakpoints, breakpoints[1:]):
        tiles.extend(FRONTIER(p, q))
    return tiles

opaque HashValue[HASH_SIZE];

struct {
    uint64 start;
    uint64 end;
    HashValue hash;
} SubtreeRef;

struct {
    uint64 tree_size;
    SubtreeRef subtrees<1..2^16-1>;
    HashValue tiles<1..2^16-1>;
} BulkSubtreeProof;
